  parts.push(exWingStrip(-G.chord / 2, -G.chord / 2 + 0.12, [1, 1, 1], UV_LIT, 0.02));   // mép sau: thấy rõ từ camera bám đuôi
  /* Người treo: thân + đầu, cách cánh G.lines mét */
