import fs from 'fs';
const R = (f, pairs) => {
  let s = fs.readFileSync(f, 'utf8');
  const nl = s.includes('\r\n') ? '\r\n' : '\n';
  for (const [a, b] of pairs) {
    const n = typeof a === 'string' ? s.split(a).length - 1 : (s.match(new RegExp(a.source, a.flags + 'g')) || []).length;
    if (n !== 1) throw new Error(f + ' khớp ' + n + ': ' + a);
    s = s.replace(a, () => b.replace(/\n/g, nl));
  }
  fs.writeFileSync(f, s);
};

R('src/config.ts', [
  [/^  speed: 25,.*$/m, `  speed: 50,           // m/s — tốc độ ngang khi cất cánh (ước lượng)
  speedMin: 15,        // m/s — tốc độ ngang nhỏ nhất, giữ Q (ước lượng)
  speedMax: 100,       // m/s — tốc độ ngang lớn nhất, giữ E (ước lượng)
  speedAccel: 30,      // m/s² — mức tăng/giảm tốc khi giữ Q/E (ước lượng)`],
  [/^  climbRate: 6,.*$/m, `  climbRate: 20,      // m/s — tốc độ lên/xuống khi giữ W/S (ước lượng)`],
  [/^  floor: 30,.*$/m, `  floor: 6,            // m — độ cao tối thiểu, y thế giới; người treo thấp hơn gốc ~4 m nên vẫn trên mặt đất, đủ chui gầm cầu (ước lượng)`],
  [`chase: { back: 18, up: 6, lag: 0.25, look: 30 },   // m phía sau, m phía trên, s trễ của camera bám đuôi, m nhìn trước (ước lượng)`,
