import fs from 'fs';
const R = (f, pairs) => {
  let s = fs.readFileSync(f, 'utf8');
  const nl = s.includes('\r\n') ? '\r\n' : '\n';
  for (const [a, b] of pairs) {
    if (s.split(a).length !== 2) throw new Error(f + ' khớp sai: ' + a);
    s = s.replace(a, () => b.replace(/\n/g, nl));
  }
  fs.writeFileSync(f, s);
};
const dec = '.github/memory-bank/decisions.md';
R(dec, [
  ['- Tốc độ ngang cố định 25 m/s; A/D rẽ (dù nghiêng), W/S lên/xuống trong sàn 30 m, trần 800 m; thả phím tự cân bằng. Không va chạm; tới mép khung bay thì dù tự vòng về, không có tường vô hình.',
   '- Tốc độ ngang 15–100 m/s, khởi đầu 50, giữ E tăng / Q giảm (bản đầu cố định 25 m/s, người dùng thấy quá chậm); A/D rẽ (dù nghiêng), W/S lên/xuống 20 m/s trong sàn 7 m, trần 800 m (sàn 30 m cũ nằm trên gầm cầu Rồng ~27 m nên không bay sát cầu được); thả phím tự cân bằng. Không va chạm; tới mép khung bay thì dù tự vòng về, không có tường vô hình. Đang tự lái về mà nhanh hơn `returnTurnSpeed` thì nghiêng và rẽ gắt theo tỉ lệ tốc độ, nếu không ở 100 m/s bán kính vòng ~167 m sẽ đụng mép.\n- Cánh in cờ đỏ sao vàng bằng atlas canvas (không ảnh ngoài), người treo dựng bằng khối bo tròn trong code, vẫn 1 Mesh. Camera bám cao 9 m và cánh nghiêng `tilt` 0,35 rad về sau là có chủ đích: camera cao 6 m nhìn gần như ngang cánh nên hình in dẹt thành một vạch.'],
